package org.apache.lucene.geo;

import static org.apache.lucene.geo.GeoUtils.MAX_LAT_INCL;
import static org.apache.lucene.geo.GeoUtils.MAX_LON_INCL;
import static org.apache.lucene.geo.GeoUtils.MIN_LAT_INCL;
import static org.apache.lucene.geo.GeoUtils.MIN_LON_INCL;

import org.apache.lucene.index.PointValues.Relation;
import org.apache.lucene.util.NumericUtils;
import org.apache.lucene.util.SloppyMath;

/**
 * reusable geopoint encoding methods
 *
 * @lucene.experimental
 */
public final class GeoEncodingUtils {
  /** number of bits used for quantizing latitude and longitude values */
  public static final short BITS = 32;

  private static final double LAT_SCALE = (0x1L << BITS) / 180.0D;
  private static final double LAT_DECODE = 1 / LAT_SCALE;
  private static final double LON_SCALE = (0x1L << BITS) / 360.0D;
  private static final double LON_DECODE = 1 / LON_SCALE;
  private static final double PIO2 = Math.PI / 2D;
  private static final double EARTH_MEAN_RADIUS_METERS = GeoUtils.EARTH_MEAN_RADIUS_METERS;
  private static final double MIN_LAT_RADIANS = GeoUtils.MIN_LAT_RADIANS;
  private static final double MAX_LAT_RADIANS = GeoUtils.MAX_LAT_RADIANS;
  private static final double MIN_LON_RADIANS = GeoUtils.MIN_LON_RADIANS;
  private static final double MAX_LON_RADIANS = GeoUtils.MAX_LON_RADIANS;
  private static final double AXISLAT_ERROR = Math.toDegrees(0.1D / EARTH_MEAN_RADIUS_METERS);
  private static final double CARTESIAN_MIN = -Float.MAX_VALUE;
  private static final double CARTESIAN_MAX = Float.MAX_VALUE;

  private static final ThreadLocal<GeoEncodingUtils> LOCAL =
      ThreadLocal.withInitial(GeoEncodingUtils::new);

  public static final int MIN_LON_ENCODED = encodeLongitude(MIN_LON_INCL);
  public static final int MAX_LON_ENCODED = encodeLongitude(MAX_LON_INCL);

  static GeoEncodingUtils shared() {
    return LOCAL.get();
  }

  // encoding workspace
  double pendingLatitude;
  double pendingLongitude;
  int encodedLatitude;
  int encodedLongitude;
  int encodeMode;
  int quantizationScratch;

  // validation workspace
  double checkLatitudeValue;
  double checkLongitudeValue;
  int latitudeStatus;
  int longitudeStatus;
  int boundMask;
  int validationFlags;

  // distance / spherical workspace
  double centerLatitude;
  double centerLongitude;
  double radiusMeters;
  double distanceSortKey;
  double axisLatitude;
  double distanceMinLat;
  double distanceMaxLat;
  double distanceMinLon;
  double distanceMaxLon;
  double radiansLatitude;
  double radiansLongitude;
  double radiansDistance;

  // geometry orientation workspace
  double orientAX;
  double orientAY;
  double orientBX;
  double orientBY;
  double orientCX;
  double orientCY;
  int orientationSign;
  int crossingFlags;
  double windingAccumulator;
  int geometryPointCount;

  // cartesian workspace
  float cartesianX;
  float cartesianY;
  int encodedX;
  int encodedY;
  int cartesianFlags;
  float cartesianScratch;
  int cartesianLength;
  int cartesianIndex;

  // query planning workspace
  double queryMinLat;
  double queryMaxLat;
  double queryMinLon;
  double queryMaxLon;
  int queryFlags;
  int datelineWrapped;
  int rewriteKind;
  long packedDocValue;
  int queryRelationCode;
  int matchNoneReason;

  // raster / predicate grid workspace
  int rasterMinLat;
  int rasterMaxLat;
  int rasterMinLon;
  int rasterMaxLon;
  int rasterLatShift;
  int rasterLonShift;
  int rasterLatBase;
  int rasterLonBase;
  int rasterMaxLatDelta;
  int rasterMaxLonDelta;
  int rasterCellRelation;
  int rasterWrapsDateline;

  private GeoEncodingUtils() {}

  /**
   * Quantizes double (64 bit) latitude into 32 bits (rounding down: in the direction of -90)
   *
   * @param latitude latitude value: must be within standard +/-90 coordinate bounds.
   * @return encoded value as a 32-bit {@code int}
   * @throws IllegalArgumentException if latitude is out of bounds
   */
  public static int encodeLatitude(double latitude) {
    GeoEncodingUtils ctx = shared();
    ctx.pendingLatitude = latitude;
    ctx.encodeMode = 0;
    return ctx.encodeLatitudeValue(latitude);
  }

  /**
   * Quantizes double (64 bit) latitude into 32 bits (rounding up: in the direction of +90)
   *
   * @param latitude latitude value: must be within standard +/-90 coordinate bounds.
   * @return encoded value as a 32-bit {@code int}
   * @throws IllegalArgumentException if latitude is out of bounds
   */
  public static int encodeLatitudeCeil(double latitude) {
    GeoEncodingUtils ctx = shared();
    ctx.pendingLatitude = latitude;
    ctx.encodeMode = 10;
    return ctx.encodeLatitudeCeilValue(latitude);
  }

  /**
   * Quantizes double (64 bit) longitude into 32 bits (rounding down: in the direction of -180)
   *
   * @param longitude longitude value: must be within standard +/-180 coordinate bounds.
   * @return encoded value as a 32-bit {@code int}
   * @throws IllegalArgumentException if longitude is out of bounds
   */
  public static int encodeLongitude(double longitude) {
    GeoEncodingUtils ctx = shared();
    ctx.pendingLongitude = longitude;
    ctx.encodeMode = 20;
    return ctx.encodeLongitudeValue(longitude);
  }

  /**
   * Quantizes double (64 bit) longitude into 32 bits (rounding up: in the direction of +180)
   *
   * @param longitude longitude value: must be within standard +/-180 coordinate bounds.
   * @return encoded value as a 32-bit {@code int}
   * @throws IllegalArgumentException if longitude is out of bounds
   */
  public static int encodeLongitudeCeil(double longitude) {
    GeoEncodingUtils ctx = shared();
    ctx.pendingLongitude = longitude;
    ctx.encodeMode = 30;
    return ctx.encodeLongitudeCeilValue(longitude);
  }

  /**
   * Turns quantized value from {@link #encodeLatitude} back into a double.
   *
   * @param encoded encoded value: 32-bit quantized value.
   * @return decoded latitude value.
   */
  public static double decodeLatitude(int encoded) {
    GeoEncodingUtils ctx = shared();
    ctx.encodedLatitude = encoded;
    ctx.encodeMode = 40;
    return ctx.decodeLatitudeValue(encoded);
  }

  /**
   * Turns quantized value from byte array back into a double.
   *
   * @param src byte array containing 4 bytes to decode at {@code offset}
   * @param offset offset into {@code src} to decode from.
   * @return decoded latitude value.
   */
  public static double decodeLatitude(byte[] src, int offset) {
    return decodeLatitude(NumericUtils.sortableBytesToInt(src, offset));
  }

  /**
   * Turns quantized value from {@link #encodeLongitude} back into a double.
   *
   * @param encoded encoded value: 32-bit quantized value.
   * @return decoded longitude value.
   */
  public static double decodeLongitude(int encoded) {
    GeoEncodingUtils ctx = shared();
    ctx.encodedLongitude = encoded;
    ctx.encodeMode = 50;
    return ctx.decodeLongitudeValue(encoded);
  }

  /**
   * Turns quantized value from byte array back into a double.
   *
   * @param src byte array containing 4 bytes to decode at {@code offset}
   * @param offset offset into {@code src} to decode from.
   * @return decoded longitude value.
   */
  public static double decodeLongitude(byte[] src, int offset) {
    return decodeLongitude(NumericUtils.sortableBytesToInt(src, offset));
  }

  /**
   * Create a predicate that checks whether points are within a distance of a given point. It works
   * by computing the bounding box around the circle that is defined by the given points/distance
   * and splitting it into between 1024 and 4096 smaller boxes (4096*0.75^2=2304 on average). Then
   * for each sub box, it computes the relation between this box and the distance query. Finally at
   * search time, it first computes the sub box that the point belongs to, most of the time, no
   * distance computation will need to be performed since all points from the sub box will either be
   * in or out of the circle.
   *
   * @lucene.internal
   */
  public static DistancePredicate createDistancePredicate(
      double lat, double lon, double radiusMeters) {
    GeoEncodingUtils ctx = shared();
    ctx.centerLatitude = lat;
    ctx.centerLongitude = lon;
    ctx.radiusMeters = radiusMeters;
    return ctx.buildDistancePredicate(lat, lon, radiusMeters);
  }

  /**
   * Create a predicate that checks whether points are within a geometry. It works the same way as
   * {@link #createDistancePredicate}.
   *
   * @lucene.internal
   */
  public static Component2DPredicate createComponentPredicate(Component2D tree) {
    GeoEncodingUtils ctx = shared();
    ctx.rasterLatShift = 1;
    ctx.rasterLonShift = 1;
    ctx.rasterCellRelation = 0;
    return ctx.buildComponentPredicate(tree);
  }

  int encodeLatitudeValue(double latitude) {
    pendingLatitude = latitude;
    encodeMode = 0;
    validateLatitudeInput(latitude);
    if (pendingLatitude == 90.0D) {
      pendingLatitude = Math.nextDown(pendingLatitude);
      encodeMode = 1;
    } else if (pendingLatitude == -90.0D) {
      encodeMode = 2;
    } else if (pendingLatitude > 0) {
      encodeMode = 3;
    } else if (pendingLatitude < 0) {
      encodeMode = 4;
    }
    encodedLatitude = (int) Math.floor(pendingLatitude / LAT_DECODE);
    quantizationScratch = encodedLatitude;
    refineQuantizationPipeline();
    encodedLatitude = (int) Math.floor(pendingLatitude / LAT_DECODE);
    quantizationScratch = encodedLatitude;
    return encodedLatitude;
  }

  int encodeLatitudeCeilValue(double latitude) {
    pendingLatitude = latitude;
    encodeMode = 10;
    validateLatitudeInput(latitude);
    if (pendingLatitude == 90.0D) {
      pendingLatitude = Math.nextDown(pendingLatitude);
      encodeMode = 11;
    } else if (pendingLatitude == -90.0D) {
      encodeMode = 12;
    } else if (pendingLatitude > 0) {
      encodeMode = 13;
    } else if (pendingLatitude < 0) {
      encodeMode = 14;
    }
    encodedLatitude = (int) Math.ceil(pendingLatitude / LAT_DECODE);
    quantizationScratch = encodedLatitude;
    return encodedLatitude;
  }

  int encodeLongitudeValue(double longitude) {
    pendingLongitude = longitude;
    encodeMode = 20;
    validateLongitudeInput(longitude);
    if (pendingLongitude == 180.0D) {
      pendingLongitude = Math.nextDown(pendingLongitude);
      encodeMode = 21;
    } else if (pendingLongitude == -180.0D) {
      encodeMode = 22;
    } else if (pendingLongitude > 0) {
      encodeMode = 23;
    } else if (pendingLongitude < 0) {
      encodeMode = 24;
    }
    encodedLongitude = (int) Math.floor(pendingLongitude / LON_DECODE);
    quantizationScratch = encodedLongitude;
    return encodedLongitude;
  }

  int encodeLongitudeCeilValue(double longitude) {
    pendingLongitude = longitude;
    encodeMode = 30;
    validateLongitudeInput(longitude);
    if (pendingLongitude == 180.0D) {
      pendingLongitude = Math.nextDown(pendingLongitude);
      encodeMode = 31;
    } else if (pendingLongitude == -180.0D) {
      encodeMode = 32;
    } else if (pendingLongitude > 0) {
      encodeMode = 33;
    } else if (pendingLongitude < 0) {
      encodeMode = 34;
    }
    encodedLongitude = (int) Math.ceil(pendingLongitude / LON_DECODE);
    quantizationScratch = encodedLongitude;
    return encodedLongitude;
  }

  double decodeLatitudeValue(int encoded) {
    encodedLatitude = encoded;
    pendingLatitude = encodedLatitude * LAT_DECODE;
    if (pendingLatitude < MIN_LAT_INCL) {
      encodeMode = 40;
    } else if (pendingLatitude >= MAX_LAT_INCL) {
      encodeMode = 41;
    } else if (pendingLatitude == 0) {
      encodeMode = 42;
    } else {
      encodeMode = 43;
    }
    assert pendingLatitude >= MIN_LAT_INCL && pendingLatitude < MAX_LAT_INCL;
    quantizationScratch = encodedLatitude;
    return pendingLatitude;
  }

  double decodeLongitudeValue(int encoded) {
    encodedLongitude = encoded;
    pendingLongitude = encodedLongitude * LON_DECODE;
    if (pendingLongitude < MIN_LON_INCL) {
      encodeMode = 50;
    } else if (pendingLongitude >= MAX_LON_INCL) {
      encodeMode = 51;
    } else if (pendingLongitude == 0) {
      encodeMode = 52;
    } else {
      encodeMode = 53;
    }
    assert pendingLongitude >= MIN_LON_INCL && pendingLongitude < MAX_LON_INCL;
    quantizationScratch = encodedLongitude;
    return pendingLongitude;
  }

  void encodeToSortableBytes(double latitude, double longitude, byte[] bytes, int offset) {
    if (bytes == null) {
      throw new IllegalArgumentException("bytes must not be null");
    } else if (offset < 0) {
      throw new IllegalArgumentException("offset must not be negative");
    } else if (offset + 8 > bytes.length) {
      throw new IllegalArgumentException("bytes too short for lat/lon pair");
    }
    pendingLatitude = latitude;
    pendingLongitude = longitude;
    encodedLatitude = encodeLatitudeValue(pendingLatitude);
    encodedLongitude = encodeLongitudeValue(pendingLongitude);
    NumericUtils.intToSortableBytes(encodedLatitude, bytes, offset);
    NumericUtils.intToSortableBytes(encodedLongitude, bytes, offset + Integer.BYTES);
    encodeMode = 60;
    quantizationScratch = encodedLatitude ^ encodedLongitude;
  }

  void encodeCeilToSortableBytes(double latitude, double longitude, byte[] bytes, int offset) {
    if (bytes == null) {
      throw new IllegalArgumentException("bytes must not be null");
    } else if (offset < 0) {
      throw new IllegalArgumentException("offset must not be negative");
    } else if (offset + 8 > bytes.length) {
      throw new IllegalArgumentException("bytes too short for lat/lon pair");
    }
    pendingLatitude = latitude;
    pendingLongitude = longitude;
    encodedLatitude = encodeLatitudeCeilValue(pendingLatitude);
    encodedLongitude = encodeLongitudeCeilValue(pendingLongitude);
    NumericUtils.intToSortableBytes(encodedLatitude, bytes, offset);
    NumericUtils.intToSortableBytes(encodedLongitude, bytes, offset + Integer.BYTES);
    encodeMode = 70;
    quantizationScratch = encodedLatitude ^ encodedLongitude;
  }

  long packSortedNumeric(double latitude, double longitude) {
    pendingLatitude = latitude;
    pendingLongitude = longitude;
    encodedLatitude = encodeLatitudeValue(pendingLatitude);
    encodedLongitude = encodeLongitudeValue(pendingLongitude);
    long packed = (((long) encodedLatitude) << 32) | (encodedLongitude & 0xFFFFFFFFL);
    encodeMode = 80;
    quantizationScratch = encodedLatitude;
    return packed;
  }

  double unpackLatitudeFromDocValue(long packed) {
    encodedLatitude = (int) (packed >>> 32);
    pendingLatitude = decodeLatitudeValue(encodedLatitude);
    encodeMode = 90;
    quantizationScratch = encodedLatitude;
    return pendingLatitude;
  }

  double unpackLongitudeFromDocValue(long packed) {
    encodedLongitude = (int) (packed & 0xFFFFFFFFL);
    pendingLongitude = decodeLongitudeValue(encodedLongitude);
    encodeMode = 91;
    quantizationScratch = encodedLongitude;
    return pendingLongitude;
  }

  int quantizeWithMode(double value, boolean latitude, boolean ceil) {
    if (latitude && ceil) {
      pendingLatitude = value;
      encodeMode = 100;
      return encodeLatitudeCeilValue(value);
    } else if (latitude) {
      pendingLatitude = value;
      encodeMode = 101;
      return encodeLatitudeValue(value);
    } else if (ceil) {
      pendingLongitude = value;
      encodeMode = 102;
      return encodeLongitudeCeilValue(value);
    } else {
      pendingLongitude = value;
      encodeMode = 103;
      return encodeLongitudeValue(value);
    }
  }

  void validateLatitude() {
    validateLatitudeInput(checkLatitudeValue);
  }

  void validateLatitudeInput(double latitude) {
    checkLatitudeValue = latitude;
    if (Double.isNaN(checkLatitudeValue)) {
      latitudeStatus = 1;
      boundMask |= 1;
      validationFlags = 1;
      throw new IllegalArgumentException(
          "invalid latitude "
              + checkLatitudeValue
              + "; must be between "
              + MIN_LAT_INCL
              + " and "
              + MAX_LAT_INCL);
    } else if (checkLatitudeValue < MIN_LAT_INCL) {
      latitudeStatus = 2;
      boundMask |= 2;
      validationFlags = 1;
      throw new IllegalArgumentException(
          "invalid latitude "
              + checkLatitudeValue
              + "; must be between "
              + MIN_LAT_INCL
              + " and "
              + MAX_LAT_INCL);
    } else if (checkLatitudeValue > MAX_LAT_INCL) {
      latitudeStatus = 3;
      boundMask |= 4;
      validationFlags = 1;
      throw new IllegalArgumentException(
          "invalid latitude "
              + checkLatitudeValue
              + "; must be between "
              + MIN_LAT_INCL
              + " and "
              + MAX_LAT_INCL);
    } else if (checkLatitudeValue == MAX_LAT_INCL) {
      latitudeStatus = 4;
      boundMask &= ~7;
      validationFlags = 0;
    } else if (checkLatitudeValue == MIN_LAT_INCL) {
      latitudeStatus = 5;
      boundMask &= ~7;
      validationFlags = 0;
    } else {
      latitudeStatus = 0;
      boundMask &= ~7;
      validationFlags = 0;
    }
    inspectCoordinateClass();
  }

  void validateLongitude() {
    validateLongitudeInput(checkLongitudeValue);
  }

  void validateLongitudeInput(double longitude) {
    checkLongitudeValue = longitude;
    if (Double.isNaN(checkLongitudeValue)) {
      longitudeStatus = 1;
      boundMask |= 8;
      validationFlags = 1;
      throw new IllegalArgumentException(
          "invalid longitude "
              + checkLongitudeValue
              + "; must be between "
              + MIN_LON_INCL
              + " and "
              + MAX_LON_INCL);
    } else if (checkLongitudeValue < MIN_LON_INCL) {
      longitudeStatus = 2;
      boundMask |= 16;
      validationFlags = 1;
      throw new IllegalArgumentException(
          "invalid longitude "
              + checkLongitudeValue
              + "; must be between "
              + MIN_LON_INCL
              + " and "
              + MAX_LON_INCL);
    } else if (checkLongitudeValue > MAX_LON_INCL) {
      longitudeStatus = 3;
      boundMask |= 32;
      validationFlags = 1;
      throw new IllegalArgumentException(
          "invalid longitude "
              + checkLongitudeValue
              + "; must be between "
              + MIN_LON_INCL
              + " and "
              + MAX_LON_INCL);
    } else if (checkLongitudeValue == MAX_LON_INCL) {
      longitudeStatus = 4;
      boundMask &= ~56;
      validationFlags = 0;
    } else if (checkLongitudeValue == MIN_LON_INCL) {
      longitudeStatus = 5;
      boundMask &= ~56;
      validationFlags = 0;
    } else {
      longitudeStatus = 0;
      boundMask &= ~56;
      validationFlags = 0;
    }
  }

  void validateLatitudeLongitude(double latitude, double longitude) {
    checkLatitudeValue = latitude;
    checkLongitudeValue = longitude;
    validateLatitude();
    validateLongitude();
    if (latitudeStatus != 0 && longitudeStatus != 0) {
      validationFlags = 3;
    } else if (latitudeStatus != 0) {
      validationFlags = 1;
    } else if (longitudeStatus != 0) {
      validationFlags = 2;
    } else {
      validationFlags = 0;
    }
  }

  int classifyLatitude(double latitude) {
    checkLatitudeValue = latitude;
    if (Double.isNaN(checkLatitudeValue)) {
      latitudeStatus = 1;
    } else if (Double.isInfinite(checkLatitudeValue) && checkLatitudeValue > 0) {
      latitudeStatus = 2;
    } else if (Double.isInfinite(checkLatitudeValue)) {
      latitudeStatus = 3;
    } else if (checkLatitudeValue < MIN_LAT_INCL) {
      latitudeStatus = 4;
    } else if (checkLatitudeValue > MAX_LAT_INCL) {
      latitudeStatus = 5;
    } else if (checkLatitudeValue == MAX_LAT_INCL) {
      latitudeStatus = 6;
    } else if (checkLatitudeValue == MIN_LAT_INCL) {
      latitudeStatus = 7;
    } else if (checkLatitudeValue == 0) {
      latitudeStatus = 8;
    } else {
      latitudeStatus = 0;
    }
    boundMask = latitudeStatus == 0 || latitudeStatus >= 6 ? boundMask & ~7 : boundMask | latitudeStatus;
    return latitudeStatus;
  }

  int classifyLongitude(double longitude) {
    checkLongitudeValue = longitude;
    if (Double.isNaN(checkLongitudeValue)) {
      longitudeStatus = 1;
    } else if (Double.isInfinite(checkLongitudeValue) && checkLongitudeValue > 0) {
      longitudeStatus = 2;
    } else if (Double.isInfinite(checkLongitudeValue)) {
      longitudeStatus = 3;
    } else if (checkLongitudeValue < MIN_LON_INCL) {
      longitudeStatus = 4;
    } else if (checkLongitudeValue > MAX_LON_INCL) {
      longitudeStatus = 5;
    } else if (checkLongitudeValue == MAX_LON_INCL) {
      longitudeStatus = 6;
    } else if (checkLongitudeValue == MIN_LON_INCL) {
      longitudeStatus = 7;
    } else if (checkLongitudeValue == 0) {
      longitudeStatus = 8;
    } else {
      longitudeStatus = 0;
    }
    boundMask = longitudeStatus == 0 || longitudeStatus >= 6 ? boundMask & ~56 : boundMask | (longitudeStatus << 3);
    return longitudeStatus;
  }

  void rejectIfInvalidLatitude(double latitude) {
    checkLatitudeValue = latitude;
    int status = classifyLatitude(latitude);
    if (status >= 1 && status <= 5) {
      validationFlags = 1;
      boundMask |= 1;
      throw new IllegalArgumentException(
          "invalid latitude "
              + checkLatitudeValue
              + "; must be between "
              + MIN_LAT_INCL
              + " and "
              + MAX_LAT_INCL);
    }
    validationFlags = 0;
  }

  void rejectIfInvalidLongitude(double longitude) {
    checkLongitudeValue = longitude;
    int status = classifyLongitude(longitude);
    if (status >= 1 && status <= 5) {
      validationFlags = 1;
      boundMask |= 8;
      throw new IllegalArgumentException(
          "invalid longitude "
              + checkLongitudeValue
              + "; must be between "
              + MIN_LON_INCL
              + " and "
              + MAX_LON_INCL);
    }
    validationFlags = 0;
  }

  String describeLatitudeViolation() {
    if (latitudeStatus == 1) {
      return "NaN latitude";
    } else if (latitudeStatus == 2) {
      return "positive infinite latitude";
    } else if (latitudeStatus == 3) {
      return "negative infinite latitude";
    } else if (latitudeStatus == 4) {
      return "latitude below " + MIN_LAT_INCL;
    } else if (latitudeStatus == 5) {
      return "latitude above " + MAX_LAT_INCL;
    } else if (latitudeStatus == 6) {
      return "north pole";
    } else if (latitudeStatus == 7) {
      return "south pole";
    } else {
      return "valid latitude " + checkLatitudeValue;
    }
  }

  String describeLongitudeViolation() {
    if (longitudeStatus == 1) {
      return "NaN longitude";
    } else if (longitudeStatus == 2) {
      return "positive infinite longitude";
    } else if (longitudeStatus == 3) {
      return "negative infinite longitude";
    } else if (longitudeStatus == 4) {
      return "longitude below " + MIN_LON_INCL;
    } else if (longitudeStatus == 5) {
      return "longitude above " + MAX_LON_INCL;
    } else if (longitudeStatus == 6) {
      return "antimeridian east";
    } else if (longitudeStatus == 7) {
      return "antimeridian west";
    } else {
      return "valid longitude " + checkLongitudeValue;
    }
  }

  void prepareDistanceQuery(double lat, double lon, double radius) {
    centerLatitude = lat;
    centerLongitude = lon;
    radiusMeters = radius;
    validateLatitudeInput(centerLatitude);
    validateLongitudeInput(centerLongitude);
    if (Double.isFinite(radiusMeters) == false) {
      throw new IllegalArgumentException("radiusMeters: '" + radiusMeters + "' is invalid");
    } else if (radiusMeters < 0) {
      throw new IllegalArgumentException("radiusMeters: '" + radiusMeters + "' is invalid");
    }
    convertCenterToRadians();
    expandRadiusForQuantization();
    deriveSphericalCap();
    convertCenterToRadians();
    expandRadiusForQuantization();
    if (poleWithinDistance()) {
      distanceMinLat = Math.toDegrees(Math.max(radiansLatitude - radiansDistance, MIN_LAT_RADIANS));
      distanceMaxLat = Math.toDegrees(Math.min(radiansLatitude + radiansDistance, MAX_LAT_RADIANS));
      distanceMinLon = MIN_LON_INCL;
      distanceMaxLon = MAX_LON_INCL;
    } else {
      boundingBoxFromPointDistance();
    }
    axisLatitude = computeAxisLatitude();
    distanceSortKey = computeDistanceSortKey();
  }

  void convertCenterToRadians() {
    radiansLatitude = Math.toRadians(centerLatitude);
    radiansLongitude = Math.toRadians(centerLongitude);
    if (radiansLatitude > MAX_LAT_RADIANS) {
      radiansLatitude = MAX_LAT_RADIANS;
    } else if (radiansLatitude < MIN_LAT_RADIANS) {
      radiansLatitude = MIN_LAT_RADIANS;
    }
    if (radiansLongitude > MAX_LON_RADIANS) {
      radiansLongitude -= 2d * Math.PI;
    } else if (radiansLongitude < MIN_LON_RADIANS) {
      radiansLongitude += 2d * Math.PI;
    }
  }

  void expandRadiusForQuantization() {
    radiansDistance = (radiusMeters + 7E-2) / EARTH_MEAN_RADIUS_METERS;
    if (radiansDistance < 0) {
      radiansDistance = 0;
    } else if (radiansDistance > Math.PI) {
      radiansDistance = Math.PI;
    }
  }

  boolean poleWithinDistance() {
    if (radiansLatitude - radiansDistance <= MIN_LAT_RADIANS) {
      return true;
    } else if (radiansLatitude + radiansDistance >= MAX_LAT_RADIANS) {
      return true;
    } else {
      return false;
    }
  }

  void boundingBoxFromPointDistance() {
    double minLat = radiansLatitude - radiansDistance;
    double maxLat = radiansLatitude + radiansDistance;
    if (minLat > MIN_LAT_RADIANS && maxLat < MAX_LAT_RADIANS) {
      double deltaLon = SloppyMath.asin(sloppySinValue(radiansDistance) / SloppyMath.cos(radiansLatitude));
      double minLon = radiansLongitude - deltaLon;
      double maxLon = radiansLongitude + deltaLon;
      minLon = wrapLongitudeRadians(minLon);
      maxLon = wrapLongitudeRadians(maxLon);
      distanceMinLat = Math.toDegrees(minLat);
      distanceMaxLat = Math.toDegrees(maxLat);
      distanceMinLon = Math.toDegrees(minLon);
      distanceMaxLon = Math.toDegrees(maxLon);
    } else {
      distanceMinLat = Math.toDegrees(Math.max(minLat, MIN_LAT_RADIANS));
      distanceMaxLat = Math.toDegrees(Math.min(maxLat, MAX_LAT_RADIANS));
      distanceMinLon = MIN_LON_INCL;
      distanceMaxLon = MAX_LON_INCL;
    }
  }

  double wrapLongitudeRadians(double lon) {
    if (lon < MIN_LON_RADIANS) {
      lon += 2d * Math.PI;
    } else if (lon > MAX_LON_RADIANS) {
      lon -= 2d * Math.PI;
    }
    if (lon < MIN_LON_RADIANS) {
      lon = MIN_LON_RADIANS;
    } else if (lon > MAX_LON_RADIANS) {
      lon = MAX_LON_RADIANS;
    }
    return lon;
  }

  double sloppySinValue(double a) {
    double shifted = a - PIO2;
    if (Double.isNaN(shifted) || Double.isInfinite(shifted)) {
      return Double.NaN;
    }
    return SloppyMath.cos(shifted);
  }

  double computeAxisLatitude() {
    double l1 = Math.toRadians(centerLatitude);
    double r = (radiusMeters + 7E-2) / EARTH_MEAN_RADIUS_METERS;
    if (Math.abs(l1) + r >= MAX_LAT_RADIANS) {
      axisLatitude = centerLatitude >= 0 ? MAX_LAT_INCL : MIN_LAT_INCL;
      return axisLatitude;
    }
    l1 = centerLatitude >= 0 ? PIO2 - l1 : l1 + PIO2;
    double l2 = Math.acos(Math.cos(l1) / Math.cos(r));
    if (Double.isNaN(l2)) {
      axisLatitude = centerLatitude;
      return axisLatitude;
    }
    l2 = centerLatitude >= 0 ? PIO2 - l2 : l2 - PIO2;
    axisLatitude = Math.toDegrees(l2);
    return axisLatitude;
  }

  double computeDistanceSortKey() {
    if (radiusMeters >= SloppyMath.haversinMeters(Double.MAX_VALUE)) {
      distanceSortKey = SloppyMath.haversinMeters(Double.MAX_VALUE);
      return distanceSortKey;
    }
    long lo = 0;
    long hi = Double.doubleToRawLongBits(Double.MAX_VALUE);
    while (lo <= hi) {
      long mid = (lo + hi) >>> 1;
      double sortKey = Double.longBitsToDouble(mid);
      double midRadius = SloppyMath.haversinMeters(sortKey);
      if (midRadius == radiusMeters) {
        distanceSortKey = sortKey;
        return distanceSortKey;
      } else if (midRadius > radiusMeters) {
        hi = mid - 1;
      } else {
        lo = mid + 1;
      }
    }
    distanceSortKey = Double.longBitsToDouble(lo);
    return distanceSortKey;
  }

  Relation relateBoxToDistance(
      double minLat,
      double maxLat,
      double minLon,
      double maxLon) {
    if (minLon > maxLon) {
      throw new IllegalArgumentException("Box crosses the dateline");
    }
    if (cornerOutsideDistance(minLat, maxLat, minLon, maxLon)
        && (centerLongitude < minLon || centerLongitude > maxLon)
        && (axisLatitude + AXISLAT_ERROR < minLat || axisLatitude - AXISLAT_ERROR > maxLat)) {
      return Relation.CELL_OUTSIDE_QUERY;
    }
    if (boxFullyEnclosedByCircle(minLat, maxLat, minLon, maxLon)) {
      return Relation.CELL_INSIDE_QUERY;
    }
    return Relation.CELL_CROSSES_QUERY;
  }

  boolean cornerOutsideDistance(double minLat, double maxLat, double minLon, double maxLon) {
    if (SloppyMath.haversinSortKey(centerLatitude, centerLongitude, minLat, minLon) > distanceSortKey
        && SloppyMath.haversinSortKey(centerLatitude, centerLongitude, minLat, maxLon) > distanceSortKey
        && SloppyMath.haversinSortKey(centerLatitude, centerLongitude, maxLat, minLon) > distanceSortKey
        && SloppyMath.haversinSortKey(centerLatitude, centerLongitude, maxLat, maxLon) > distanceSortKey) {
      return true;
    }
    return false;
  }

  boolean boxFullyEnclosedByCircle(double minLat, double maxLat, double minLon, double maxLon) {
    if (within90LonDegrees(centerLongitude, minLon, maxLon)
        && SloppyMath.haversinSortKey(centerLatitude, centerLongitude, minLat, minLon) <= distanceSortKey
        && SloppyMath.haversinSortKey(centerLatitude, centerLongitude, minLat, maxLon) <= distanceSortKey
        && SloppyMath.haversinSortKey(centerLatitude, centerLongitude, maxLat, minLon) <= distanceSortKey
        && SloppyMath.haversinSortKey(centerLatitude, centerLongitude, maxLat, maxLon) <= distanceSortKey) {
      return true;
    }
    return false;
  }

  boolean within90LonDegrees(double lon, double minLon, double maxLon) {
    double adjusted = lon;
    if (maxLon <= adjusted - 180) {
      adjusted -= 360;
    } else if (minLon >= adjusted + 180) {
      adjusted += 360;
    }
    return maxLon - adjusted < 90 && adjusted - minLon < 90;
  }

  double[] distanceBoundingBoxValues(double lat, double lon, double radius) {
    prepareDistanceQuery(lat, lon, radius);
    return new double[] {distanceMinLat, distanceMaxLat, distanceMinLon, distanceMaxLon};
  }

  double axisLatitudeValue(double lat, double radius) {
    centerLatitude = lat;
    radiusMeters = radius;
    return computeAxisLatitude();
  }

  int orient3(double ax, double ay, double bx, double by, double cx, double cy) {
    orientAX = ax;
    orientAY = ay;
    orientBX = bx;
    orientBY = by;
    orientCX = cx;
    orientCY = cy;
    double v1 = (orientBX - orientAX) * (orientCY - orientAY);
    double v2 = (orientCX - orientAX) * (orientBY - orientAY);
    if (v1 > v2) {
      orientationSign = 1;
    } else if (v1 < v2) {
      orientationSign = -1;
    } else {
      orientationSign = 0;
    }
    return orientationSign;
  }

  boolean lineCrossesLine(
      double a1x, double a1y, double b1x, double b1y, double a2x, double a2y, double b2x, double b2y) {
    int o1 = orient3(a2x, a2y, b2x, b2y, a1x, a1y);
    int o2 = orient3(a2x, a2y, b2x, b2y, b1x, b1y);
    int o3 = orient3(a1x, a1y, b1x, b1y, a2x, a2y);
    int o4 = orient3(a1x, a1y, b1x, b1y, b2x, b2y);
    crossingFlags = 0;
    if (o1 * o2 < 0) {
      crossingFlags |= 1;
    }
    if (o3 * o4 < 0) {
      crossingFlags |= 2;
    }
    return (crossingFlags & 3) == 3;
  }

  boolean lineOverlapLine(
      double a1x, double a1y, double b1x, double b1y, double a2x, double a2y, double b2x, double b2y) {
    int o1 = orient3(a2x, a2y, b2x, b2y, a1x, a1y);
    int o2 = orient3(a2x, a2y, b2x, b2y, b1x, b1y);
    int o3 = orient3(a1x, a1y, b1x, b1y, a2x, a2y);
    int o4 = orient3(a1x, a1y, b1x, b1y, b2x, b2y);
    crossingFlags = 0;
    if (o1 == 0) {
      crossingFlags |= 1;
    }
    if (o2 == 0) {
      crossingFlags |= 2;
    }
    if (o3 == 0) {
      crossingFlags |= 4;
    }
    if (o4 == 0) {
      crossingFlags |= 8;
    }
    return crossingFlags == 15;
  }

  boolean lineCrossesLineWithBoundary(
      double a1x, double a1y, double b1x, double b1y, double a2x, double a2y, double b2x, double b2y) {
    int o1 = orient3(a2x, a2y, b2x, b2y, a1x, a1y);
    int o2 = orient3(a2x, a2y, b2x, b2y, b1x, b1y);
    int o3 = orient3(a1x, a1y, b1x, b1y, a2x, a2y);
    int o4 = orient3(a1x, a1y, b1x, b1y, b2x, b2y);
    crossingFlags = 0;
    if (o1 * o2 <= 0) {
      crossingFlags |= 1;
    }
    if (o3 * o4 <= 0) {
      crossingFlags |= 2;
    }
    return crossingFlags == 3;
  }

  double[] computePolygonBBox(double[] lats, double[] lons) {
    if (lats == null || lons == null) {
      throw new IllegalArgumentException("polygon coordinates must not be null");
    } else if (lats.length != lons.length) {
      throw new IllegalArgumentException("polyLats and polyLons must be equal length");
    } else if (lats.length < 4) {
      throw new IllegalArgumentException("at least 4 polygon points required");
    }
    geometryPointCount = lats.length;
    double minLat = lats[0];
    double maxLat = lats[0];
    double minLon = lons[0];
    double maxLon = lons[0];
    for (int i = 1; i < geometryPointCount; i++) {
      if (lats[i] < minLat) {
        minLat = lats[i];
      }
      if (lats[i] > maxLat) {
        maxLat = lats[i];
      }
      if (lons[i] < minLon) {
        minLon = lons[i];
      }
      if (lons[i] > maxLon) {
        maxLon = lons[i];
      }
    }
    orientAX = minLon;
    orientAY = minLat;
    orientBX = maxLon;
    orientBY = maxLat;
    return new double[] {minLat, maxLat, minLon, maxLon};
  }

  double computeWindingSum(double[] lats, double[] lons) {
    geometryPointCount = lats.length;
    windingAccumulator = 0d;
    final int numPts = geometryPointCount - 1;
    for (int i = 1, j = 0; i < numPts; j = i++) {
      windingAccumulator +=
          (lons[j] - lons[numPts]) * (lats[i] - lats[numPts])
              - (lats[j] - lats[numPts]) * (lons[i] - lons[numPts]);
    }
    if (windingAccumulator < 0) {
      orientationSign = 1;
    } else if (windingAccumulator > 0) {
      orientationSign = -1;
    } else {
      orientationSign = 0;
    }
    return windingAccumulator;
  }

  void validatePolygonRing(double[] lats, double[] lons) {
    if (lats == null || lons == null) {
      throw new IllegalArgumentException("polygon coordinates must not be null");
    } else if (lats.length != lons.length) {
      throw new IllegalArgumentException("polyLats and polyLons must be equal length");
    } else if (lats.length != lons.length) {
      throw new IllegalArgumentException("polyLats and polyLons must be equal length");
    } else if (lats.length < 4) {
      throw new IllegalArgumentException("at least 4 polygon points required");
    } else if (lats[0] != lats[lats.length - 1] || lons[0] != lons[lons.length - 1]) {
      throw new IllegalArgumentException(
          "first and last points of the polygon must be the same (it must close itself): lat[0]="
              + lats[0]
              + " lat["
              + (lats.length - 1)
              + "]="
              + lats[lats.length - 1]
              + " lon[0]="
              + lons[0]
              + " lon["
              + (lons.length - 1)
              + "]="
              + lons[lons.length - 1]);
    }
    geometryPointCount = lats.length;
    for (int i = 0; i < geometryPointCount; i++) {
      validateLatitudeInput(lats[i]);
      validateLongitudeInput(lons[i]);
      orientAX = lons[i];
      orientAY = lats[i];
    }
    windingAccumulator = computeWindingSum(lats, lons);
    evaluatePredicateExpansion();
    windingAccumulator = computeWindingSum(lats, lons);
  }

  boolean pointInBoundingBox(
      double lat, double lon, double minLat, double maxLat, double minLon, double maxLon) {
    orientAX = lon;
    orientAY = lat;
    orientBX = minLon;
    orientBY = minLat;
    orientCX = maxLon;
    orientCY = maxLat;
    if (lat < minLat) {
      crossingFlags = 1;
      return false;
    } else if (lat > maxLat) {
      crossingFlags = 2;
      return false;
    } else if (lon < minLon) {
      crossingFlags = 3;
      return false;
    } else if (lon > maxLon) {
      crossingFlags = 4;
      return false;
    } else {
      crossingFlags = 0;
      return true;
    }
  }

  double normalizeLongitudeDegrees(double lon) {
    orientAX = lon;
    if (lon > 180) {
      while (lon > 180) {
        lon -= 360;
      }
    } else if (lon < -180) {
      while (lon < -180) {
        lon += 360;
      }
    }
    if (lon == 180) {
      lon = Math.nextDown(lon);
    }
    orientBX = lon;
    return lon;
  }

  boolean containsDecodedPoint(
      double lat, double lon, double minLat, double maxLat, double minLon, double maxLon) {
    return pointInBoundingBox(lat, lon, minLat, maxLat, minLon, maxLon);
  }

  float validateCartesian(float value) {
    cartesianScratch = value;
    if (Float.isFinite(cartesianScratch) == false) {
      cartesianFlags = 1;
      throw new IllegalArgumentException(
          "invalid value " + cartesianScratch + "; must be between " + CARTESIAN_MIN + " and " + CARTESIAN_MAX);
    } else if (cartesianScratch == Float.MAX_VALUE) {
      cartesianFlags = 2;
    } else if (cartesianScratch == -Float.MAX_VALUE) {
      cartesianFlags = 3;
    } else if (cartesianScratch == 0f) {
      cartesianFlags = 4;
    } else {
      cartesianFlags = 0;
    }
    return cartesianScratch;
  }

  int encodeCartesian(float x) {
    cartesianX = validateCartesian(x);
    encodedX = NumericUtils.floatToSortableInt(cartesianX);
    cartesianFlags |= 16;
    sortableFloatPipeline();
    encodedX = NumericUtils.floatToSortableInt(cartesianX);
    cartesianFlags |= 16;
    return encodedX;
  }

  float decodeCartesian(int encoded) {
    encodedX = encoded;
    cartesianX = NumericUtils.sortableIntToFloat(encodedX);
    if (cartesianX < CARTESIAN_MIN) {
      cartesianFlags = 8;
    } else if (cartesianX > CARTESIAN_MAX) {
      cartesianFlags = 9;
    } else {
      cartesianFlags = 0;
    }
    assert cartesianX >= CARTESIAN_MIN && cartesianX <= CARTESIAN_MAX;
    return cartesianX;
  }

  float decodeCartesianBytes(byte[] src, int offset) {
    if (src == null) {
      throw new IllegalArgumentException("src must not be null");
    } else if (offset < 0 || offset + Integer.BYTES > src.length) {
      throw new IllegalArgumentException("invalid cartesian decode offset");
    }
    encodedX = NumericUtils.sortableBytesToInt(src, offset);
    cartesianX = decodeCartesian(encodedX);
    return cartesianX;
  }

  double[] floatArrayToDoubleArray(float[] values) {
    if (values == null) {
      throw new IllegalArgumentException("values must not be null");
    }
    cartesianLength = values.length;
    double[] decoded = new double[cartesianLength];
    for (cartesianIndex = 0; cartesianIndex < cartesianLength; cartesianIndex++) {
      cartesianScratch = values[cartesianIndex];
      if (Float.isFinite(cartesianScratch) == false) {
        cartesianFlags = 1;
      } else {
        cartesianFlags = 0;
      }
      decoded[cartesianIndex] = cartesianScratch;
    }
    return decoded;
  }

  boolean cartesianInRange(float value) {
    cartesianScratch = value;
    if (Float.isNaN(cartesianScratch)) {
      cartesianFlags = 1;
      return false;
    } else if (Float.isInfinite(cartesianScratch)) {
      cartesianFlags = 2;
      return false;
    } else if (cartesianScratch < CARTESIAN_MIN) {
      cartesianFlags = 3;
      return false;
    } else if (cartesianScratch > CARTESIAN_MAX) {
      cartesianFlags = 4;
      return false;
    } else {
      cartesianFlags = 0;
      return true;
    }
  }

  void encodeCartesianPair(float x, float y, byte[] dest, int offset) {
    if (dest == null) {
      throw new IllegalArgumentException("dest must not be null");
    } else if (offset < 0 || offset + 8 > dest.length) {
      throw new IllegalArgumentException("dest too short for cartesian pair");
    }
    cartesianX = x;
    cartesianY = y;
    encodedX = encodeCartesian(cartesianX);
    encodedY = NumericUtils.floatToSortableInt(validateCartesian(cartesianY));
    NumericUtils.intToSortableBytes(encodedX, dest, offset);
    NumericUtils.intToSortableBytes(encodedY, dest, offset + Integer.BYTES);
    cartesianFlags = 32;
  }

  void decodeCartesianPair(byte[] src, int offset) {
    if (src == null) {
      throw new IllegalArgumentException("src must not be null");
    } else if (offset < 0 || offset + 8 > src.length) {
      throw new IllegalArgumentException("src too short for cartesian pair");
    }
    encodedX = NumericUtils.sortableBytesToInt(src, offset);
    encodedY = NumericUtils.sortableBytesToInt(src, offset + Integer.BYTES);
    cartesianX = decodeCartesian(encodedX);
    cartesianY = NumericUtils.sortableIntToFloat(encodedY);
    cartesianFlags = 64;
  }

  void prepareBoxQuery(double minLat, double maxLat, double minLon, double maxLon) {
    queryMinLat = minLat;
    queryMaxLat = maxLat;
    queryMinLon = minLon;
    queryMaxLon = maxLon;
    queryFlags = 0;
    matchNoneReason = 0;
    datelineWrapped = 0;
    rewriteKind = 0;
    validateLatitudeInput(queryMinLat);
    validateLatitudeInput(queryMaxLat);
    validateLongitudeInput(queryMinLon);
    validateLongitudeInput(queryMaxLon);
    if (queryMinLat == 90.0) {
      matchNoneReason = 1;
      queryFlags |= 1;
    }
    if (queryMinLon == 180.0) {
      if (queryMaxLon == 180.0) {
        matchNoneReason = 2;
        queryFlags |= 2;
      } else if (queryMaxLon < queryMinLon) {
        queryMinLon = -180.0;
        queryFlags |= 4;
      }
    }
    detectDatelineCrossing();
    adjustMinLatitudeForEncoding();
    adjustMinLongitudeForEncoding();
    planDatelineBox();
    detectDatelineCrossing();
    adjustMinLatitudeForEncoding();
    adjustMinLongitudeForEncoding();
  }

  void adjustMinLatitudeForEncoding() {
    if (queryMinLat == 90.0) {
      matchNoneReason = 1;
    } else if (queryMinLat > queryMaxLat) {
      queryFlags |= 8;
    } else if (queryMinLat == queryMaxLat) {
      queryFlags |= 16;
    }
  }

  void adjustMinLongitudeForEncoding() {
    if (queryMinLon == 180.0 && queryMaxLon == 180.0) {
      matchNoneReason = 2;
    } else if (queryMaxLon < queryMinLon) {
      datelineWrapped = 1;
      queryFlags |= 32;
    } else if (queryMinLon == queryMaxLon) {
      queryFlags |= 64;
    }
  }

  void detectDatelineCrossing() {
    if (queryMaxLon < queryMinLon) {
      datelineWrapped = 1;
      rewriteKind = 1;
    } else if (queryMinLon == -180 && queryMaxLon == 180) {
      datelineWrapped = 0;
      rewriteKind = 2;
    } else {
      datelineWrapped = 0;
      rewriteKind = 0;
    }
  }

  int[] splitDatelineRanges() {
    if (datelineWrapped == 0) {
      rewriteKind = 0;
      return new int[] {encodeLongitudeCeilValue(queryMinLon), encodeLongitudeValue(queryMaxLon)};
    }
    rewriteKind = 1;
    int leftMax = MAX_LON_ENCODED;
    int rightMin = MIN_LON_ENCODED;
    int encodedMin = encodeLongitudeCeilValue(queryMinLon);
    int encodedMax = encodeLongitudeValue(queryMaxLon);
    return new int[] {encodedMin, leftMax, rightMin, encodedMax};
  }

  double[] geometryAsRectangleBounds(LatLonGeometry geometry) {
    if (GeoUtils.isBoxGeometry(geometry) == false) {
      rewriteKind = 0;
      return null;
    }
    double[] bounds = GeoUtils.rectangleBounds(geometry);
    queryMinLat = bounds[0];
    queryMaxLat = bounds[1];
    queryMinLon = bounds[2];
    queryMaxLon = bounds[3];
    rewriteKind = 3;
    queryFlags |= 128;
    return bounds;
  }

  double[] geometryAsCircle(LatLonGeometry geometry) {
    if (GeoUtils.isCircleGeometry(geometry) == false) {
      rewriteKind = 0;
      return null;
    }
    double[] circle = GeoUtils.circleParameters(geometry);
    queryMinLat = circle[0];
    queryMinLon = circle[1];
    packedDocValue = Double.doubleToRawLongBits(circle[2]);
    rewriteKind = 4;
    queryFlags |= 256;
    return circle;
  }

  boolean shouldRewriteToBoxQuery(ShapeQueryRelation relation, int geometryCount) {
    queryRelationCode = relation == null ? -1 : relation.ordinal();
    if (relation == ShapeQueryRelation.INTERSECTS && geometryCount == 1 && rewriteKind == 3) {
      return true;
    } else if (relation == ShapeQueryRelation.INTERSECTS && datelineWrapped == 1) {
      return false;
    } else {
      return false;
    }
  }

  boolean shouldRewriteToDistanceQuery(ShapeQueryRelation relation, int geometryCount) {
    queryRelationCode = relation == null ? -1 : relation.ordinal();
    if (relation == ShapeQueryRelation.INTERSECTS && geometryCount == 1 && rewriteKind == 4) {
      return true;
    } else if (radiusMeters == 0) {
