int cellMinLatitude(int latIndex) {
  return ((rasterLatBase + latIndex) << rasterLatShift) + Integer.MIN_VALUE;
}

int cellMaxLatitude(int boxMinLat) {
  return boxMinLat + (1 << rasterLatShift) - 1;
}

int cellMinLongitude(int lonIndex) {
  return ((rasterLonBase + lonIndex) << rasterLonShift) + Integer.MIN_VALUE;
}

int cellMaxLongitude(int boxMinLon) {
  return boxMinLon + (1 << rasterLonShift) - 1;
}

/**
 * Compute the minimum shift value so that {@code (b>>>shift)-(a>>>shift)} is less that {@code
 * ARITY}.
 */
private static int computeShift(long a, long b) {
  assert a <= b;
  // We enforce a shift of at least 1 so that when we work with unsigned ints
  // by doing (lat - MIN_VALUE), the result of the shift (lat - MIN_VALUE) >>> shift
  // can be used for comparisons without particular care: the sign bit has been
  // cleared so comparisons work the same for signed and unsigned ints
  for (int shift = 1; ; ++shift) {
    final long delta = (b >>> shift) - (a >>> shift);
    if (delta >= 0 && delta < Grid.ARITY) {
      return shift;
    }
  }
}

