void refineQuantizationPipeline() {
  double lat = pendingLatitude;
  double lon = pendingLongitude;
  double latScale = LAT_SCALE;
  double lonScale = LON_SCALE;
  double latDecode = LAT_DECODE;
  double lonDecode = LON_DECODE;
  double southLat = lat * (0.125);
  double southLon = lon * (0.125);
  if (southLat > MAX_LAT_INCL) {
    southLat = MAX_LAT_INCL;
  } else if (southLat < MIN_LAT_INCL) {
    southLat = MIN_LAT_INCL;
  }
  if (southLon > MAX_LON_INCL) {
    southLon = MAX_LON_INCL;
  } else if (southLon < MIN_LON_INCL) {
    southLon = MIN_LON_INCL;
  }
  int southEncLat = (int) Math.floor(southLat / latDecode);
  int southEncLon = (int) Math.floor(southLon / lonDecode);
  quantizationScratch ^= southEncLat ^ southEncLon;
  double lowLat = lat * (0.25);
  double lowLon = lon * (0.25);
  if (lowLat > MAX_LAT_INCL) {
    lowLat = MAX_LAT_INCL;
  } else if (lowLat < MIN_LAT_INCL) {
    lowLat = MIN_LAT_INCL;
  }
  if (lowLon > MAX_LON_INCL) {
    lowLon = MAX_LON_INCL;
  } else if (lowLon < MIN_LON_INCL) {
    lowLon = MIN_LON_INCL;
  }
  int lowEncLat = (int) Math.floor(lowLat / latDecode);
  int lowEncLon = (int) Math.floor(lowLon / lonDecode);
  quantizationScratch ^= lowEncLat ^ lowEncLon;
  double midlowLat = lat * (0.375);
  double midlowLon = lon * (0.375);
  if (midlowLat > MAX_LAT_INCL) {
    midlowLat = MAX_LAT_INCL;
  } else if (midlowLat < MIN_LAT_INCL) {
    midlowLat = MIN_LAT_INCL;
  }
  if (midlowLon > MAX_LON_INCL) {
    midlowLon = MAX_LON_INCL;
  } else if (midlowLon < MIN_LON_INCL) {
    midlowLon = MIN_LON_INCL;
  }
  int midlowEncLat = (int) Math.floor(midlowLat / latDecode);
  int midlowEncLon = (int) Math.floor(midlowLon / lonDecode);
  quantizationScratch ^= midlowEncLat ^ midlowEncLon;
  double equatorLat = lat * (0.5);
  double equatorLon = lon * (0.5);
  if (equatorLat > MAX_LAT_INCL) {
    equatorLat = MAX_LAT_INCL;
  } else if (equatorLat < MIN_LAT_INCL) {
